css:
.fid-bond-ref{--fbr-bg:#0D1017;--fbr-ln:#1D2331;--fbr-l2:#262E40;--fbr-tx:#D5DBE7;--fbr-dim:#7A8499;--fbr-mut:#4D566A;--fbr-acc:#F2A93B;--fbr-up:#35C98A;--fbr-dn:#F25F6B;--fbr-inf:#5AA9FF;box-sizing:border-box;width:100%;min-width:260px;background:var(--fbr-bg);border:1px solid var(--fbr-ln);border-radius:4px;color:var(--fbr-tx);font:10.5px/1.35 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;overflow:hidden;outline:none}
.fid-bond-ref *{box-sizing:border-box}
.fid-bond-ref:focus-visible{box-shadow:0 0 0 1px var(--fbr-acc)}
.fid-bond-ref-hd{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:2px 6px;padding:6px 8px 2px;background:linear-gradient(#141925,#0D1017)}
.fid-bond-ref-tk{color:var(--fbr-acc);font-weight:700;font-size:11.5px;letter-spacing:.02em;white-space:nowrap}
.fid-bond-ref-tk em{font-style:normal;font-weight:400;color:var(--fbr-mut);font-size:9.5px;margin-left:2px}
.fid-bond-ref-rt{color:var(--fbr-tx);font-size:10px;white-space:nowrap}
.fid-bond-ref-rt i{font-style:normal;color:var(--fbr-up);font-size:9px;margin-left:3px;border:1px solid #1F4A38;padding:0 3px;border-radius:2px}
.fid-bond-ref-sub{padding:0 8px 3px;color:var(--fbr-dim);font:9.5px/1.3 system-ui,-apple-system,Segoe UI,sans-serif}
.fid-bond-ref-ids{display:flex;flex-wrap:wrap;gap:2px 10px;padding:3px 8px;border-top:1px solid var(--fbr-ln);border-bottom:1px solid var(--fbr-ln);color:var(--fbr-mut);font-size:9.5px}
.fid-bond-ref-ids b{color:var(--fbr-tx);font-weight:400}
.fid-bond-ref-solve{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;padding:6px 8px}
.fid-bond-ref-f{display:flex;flex-direction:column;gap:2px;min-width:0}
.fid-bond-ref-f span{color:var(--fbr-dim);font-size:9px;text-transform:uppercase;letter-spacing:.06em}
.fid-bond-ref-f input{width:100%;min-width:0;background:#07090E;border:1px solid var(--fbr-l2);border-radius:2px;color:#FFE3B0;font:700 12px/1 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;text-align:right;padding:4px 5px;outline:none}
.fid-bond-ref-f input:focus{border-color:var(--fbr-acc);background:#16120A}
.fid-bond-ref-f input.fid-bond-ref-err{border-color:var(--fbr-dn);color:var(--fbr-dn)}
.fid-bond-ref-f input.fid-bond-ref-hot{animation:fid-bond-ref-flash .6s ease-out}
.fid-bond-ref-grid{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--fbr-ln)}
.fid-bond-ref-grid div,.fid-bond-ref-pos div{display:flex;justify-content:space-between;gap:6px;padding:2px 8px;border-bottom:1px solid #141925;min-width:0}
.fid-bond-ref-grid div:nth-child(odd){border-right:1px solid #141925}
.fid-bond-ref-grid span,.fid-bond-ref-pos span{color:var(--fbr-dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fid-bond-ref-grid b,.fid-bond-ref-pos b{font-weight:400;text-align:right;white-space:nowrap}
.fid-bond-ref-pos,.fid-bond-ref-shk{border-top:1px solid var(--fbr-ln)}
.fid-bond-ref-pos b[data-o="pd"]{color:var(--fbr-acc)}
.fid-bond-ref .fid-bond-ref-ph{display:block;padding:4px 8px 2px;color:var(--fbr-inf);font:600 9px/1.2 system-ui,-apple-system,Segoe UI,sans-serif;letter-spacing:.08em;border-bottom:0}
.fid-bond-ref-sr{display:grid;grid-template-columns:48px 1fr 1fr 1fr;gap:4px;padding:1px 8px;text-align:right}
.fid-bond-ref-sr span:first-child{text-align:left;color:var(--fbr-dim)}
.fid-bond-ref-sr .fid-bond-ref-u{color:var(--fbr-up)}
.fid-bond-ref-sr .fid-bond-ref-d{color:var(--fbr-dn)}
.fid-bond-ref-sr .fid-bond-ref-m{color:var(--fbr-mut)}
.fid-bond-ref-ft{margin-top:3px;padding:4px 8px;border-top:1px solid var(--fbr-ln);color:var(--fbr-mut);font-size:9px;background:#0A0D13}
.fid-bond-ref-ft kbd{font:inherit;color:var(--fbr-dim);border:1px solid var(--fbr-l2);border-radius:2px;padding:0 3px;margin-right:1px}
@keyframes fid-bond-ref-flash{from{background:#3A2A0A}to{background:#16120A}}
@media (prefers-reduced-motion: reduce){
.fid-bond-ref .fid-bond-ref-f input.fid-bond-ref-hot{animation:none}
.fid-bond-ref *{transition:none}
}

js:
var C = 4.375, F = 2, FACE = 5000000, BENCH = 3.912, SWAP = 3.705;
var SET = Date.UTC(2026, 8, 25), MAT = Date.UTC(2034, 2, 15);
var MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function ymd(t) { var d = new Date(t); return [d.getUTCFullYear(), d.getUTCMonth() + 1, d.getUTCDate()]; }
function d360(a, b) { var x = ymd(a), z = ymd(b), d1 = Math.min(x[2], 30), d2 = z[2]; if (d2 === 31 && d1 === 30) d2 = 30; return 360 * (z[0] - x[0]) + 30 * (z[1] - x[1]) + (d2 - d1); }
function addM(t, m) { var d = new Date(t); return Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + m, d.getUTCDate()); }
function dstr(t) { var d = ymd(t); return (d[2] < 10 ? '0' : '') + d[2] + '-' + MON[d[1] - 1] + '-' + String(d[0]).slice(2); }
/* coupon schedule: walk back from maturity to the last coupon on or before settle */
var dates = [], cur = MAT;
while (cur > SET) { dates.unshift(cur); cur = addM(cur, -12 / F); }
var PREV = cur, N = dates.length, PER = 360 / F;
var AI = C / F * d360(PREV, SET) / PER;            /* accrued per 100 */
var W = d360(SET, dates[0]) / PER;                 /* fraction of period to next coupon */
function calc(y) {
  var v = 1 / (1 + y / F), P = 0, T = 0, X = 0;
  for (var k = 1; k <= N; k++) {
    var cf = C / F + (k === N ? 100 : 0), t = k - 1 + W, pv = cf * Math.pow(v, t);
    P += pv; T += t * pv; X += t * (t + 1) * pv;
  }
  var mac = T / P / F;
  return { P: P, mac: mac, mod: mac / (1 + y / F), cvx: X * v * v / P / (F * F) };
}
function solve(dirty) {
  var y = 0.05;
  for (var i = 0; i < 40; i++) { var r = calc(y), f = r.P - dirty; if (Math.abs(f) < 1e-11) break; y += f / (r.mod * r.P); }
  return y;
}
function fx(x, d) { var s = Math.abs(x).toFixed(d).split('.'); s[0] = s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ','); return s.join('.'); }
function sg(x, d) { return (x > 0 ? '+' : x < 0 ? '−' : '±') + fx(x, d); }
function r2(x) { return Math.round(x * 100) / 100; }
var inp = { px: root.querySelector('[data-k="px"]'), y: root.querySelector('[data-k="y"]'), g: root.querySelector('[data-k="g"]') };
function out(k, v) { var e = root.querySelector('[data-o="' + k + '"]'); if (e) e.textContent = v; }
var Y = solve(97.25 + AI);
function shockRow(el, bp, base) {
  var dy = bp / 10000, full = calc(Y + dy).P - base.P, apx = (-base.mod * dy + 0.5 * base.cvx * dy * dy) * base.P;
  var cls = full >= 0 ? 'fid-bond-ref-u' : 'fid-bond-ref-d', arr = full >= 0 ? '▲' : '▼';
  el.innerHTML = '<span>' + (bp > 0 ? '+' : '−') + Math.abs(bp) + 'bp</span><span>' + (calc(Y + dy).P - AI).toFixed(3) +
    '</span><span class="' + cls + '">' + arr + sg(full, 3) + '</span><span class="fid-bond-ref-m">≈' + sg(apx, 3) + '</span>';
}
function render(skip) {
  var r = calc(Y), clean = r.P - AI;
  if (skip !== 'px') inp.px.value = clean.toFixed(3);
  if (skip !== 'y') inp.y.value = (Y * 100).toFixed(4);
  if (skip !== 'g') inp.g.value = ((Y * 100 - BENCH) * 100).toFixed(1);
  for (var k in inp) inp[k].classList.remove('fid-bond-ref-err');
  out('nxt', dstr(dates[0]));
  out('left', String(N));
  out('ai', AI.toFixed(5));
  out('dp', r.P.toFixed(5));
  out('mac', r.mac.toFixed(4));
  out('mod', r.mod.toFixed(4));
  out('cvx', r.cvx.toFixed(2));
  out('dv', '$' + fx(r.mod * r.P, 2));
  out('is', sg((Y * 100 - SWAP) * 100, 1) + 'bp');
  var pp = r2(clean / 100 * FACE), pa = r2(AI / 100 * FACE);
  out('pp', fx(pp, 2)); out('pa', fx(pa, 2)); out('pn', fx(pp + pa, 2));
  out('pd', '$' + fx(r.mod * r.P / 100 * FACE / 10000, 2));
  shockRow(root.querySelector('[data-o="s1"]'), 25, r);
  shockRow(root.querySelector('[data-o="s2"]'), -25, r);
}
function apply(k, raw) {
  var v = parseFloat(String(raw).replace(/,/g, ''));
  if (!isFinite(v)) return false;
  var y;
  if (k === 'px') { if (v <= 20 || v >= 200) return false; y = solve(v + AI); }
  else if (k === 'y') { if (v <= -2 || v >= 25) return false; y = v / 100; }
  else { y = (BENCH + v / 100) / 100; if (y <= -0.02 || y >= 0.25) return false; }
  Y = y; return true;
}
function flash(el) { el.classList.remove('fid-bond-ref-hot'); void el.offsetWidth; el.classList.add('fid-bond-ref-hot'); }
Object.keys(inp).forEach(function (k) {
  var el = inp[k];
  el.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
      e.preventDefault(); e.stopPropagation();
      var step = { px: 0.05, y: 0.01, g: 1 }[k] * (e.shiftKey ? 5 : 1) * (e.key === 'ArrowUp' ? 1 : -1);
      var base = parseFloat(el.value) || 0, dec = { px: 3, y: 4, g: 1 }[k];
      if (apply(k, (base + step).toFixed(dec))) { render(); flash(el); }
    } else if (e.key === 'Enter') {
      e.preventDefault(); e.stopPropagation();
      if (apply(k, el.value)) { render(); flash(el); } else el.classList.add('fid-bond-ref-err');
    } else if (e.key === 'Escape') {
      e.preventDefault(); e.stopPropagation(); render(); root.focus();
    }
  });
  el.addEventListener('blur', function () { render(); });
});
root.addEventListener('keydown', function (e) {
  if (e.target !== root) return;
  var m = { p: 'px', y: 'y', g: 'g' }[e.key.toLowerCase()];
  if (m) { e.preventDefault(); inp[m].focus(); inp[m].select(); }
});
render();

css:
.fid-ladder{--fl-bg:#0D1017;--fl-ln:#1D2331;--fl-tx:#D5DBE7;--fl-dim:#7A8499;--fl-mut:#4D566A;--fl-acc:#F2A93B;--fl-g:#4F7FD0;--fl-a:#3BB3A6;--fl-b:#D9973A;box-sizing:border-box;width:100%;min-width:260px;background:var(--fl-bg);border:1px solid var(--fl-ln);border-radius:4px;color:var(--fl-tx);font:10px/1.35 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;overflow:hidden;outline:none}
.fid-ladder *{box-sizing:border-box}
.fid-ladder:focus-visible{box-shadow:0 0 0 1px var(--fl-acc)}
.fid-ladder-hd{display:flex;justify-content:space-between;align-items:baseline;gap:8px;padding:6px 8px 4px;border-bottom:1px solid var(--fl-ln);background:linear-gradient(#141925,#0D1017)}
.fid-ladder-t{white-space:nowrap;font:700 10.5px/1 system-ui,-apple-system,Segoe UI,sans-serif;letter-spacing:.1em;color:var(--fl-acc)}
.fid-ladder-m{color:var(--fl-mut);font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fid-ladder-bar{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:4px 8px;padding:5px 8px}
.fid-ladder-tabs{display:flex;border:1px solid #262E40;border-radius:3px;overflow:hidden}
.fid-ladder-tabs button{all:unset;cursor:pointer;padding:2px 7px;font:600 9px/1.4 system-ui,-apple-system,Segoe UI,sans-serif;letter-spacing:.06em;color:var(--fl-dim)}
.fid-ladder-tabs button[aria-selected="true"]{background:#262E40;color:#fff}
.fid-ladder-tabs button:focus-visible{outline:1px solid var(--fl-acc);outline-offset:-1px}
.fid-ladder-lg{display:flex;gap:8px;color:var(--fl-dim);font-size:9px}
.fid-ladder-lg i{display:inline-block;width:7px;height:7px;margin-right:3px;border-radius:1px;vertical-align:0}
.fid-ladder-cols,.fid-ladder-row{display:grid;grid-template-columns:34px 1fr 50px 44px;gap:6px;align-items:center;padding:0 8px}
.fid-ladder-cols{color:var(--fl-mut);font-size:8.5px;letter-spacing:.06em;padding-bottom:2px;border-bottom:1px solid var(--fl-ln)}
.fid-ladder-cols span:nth-child(n+3){text-align:right}
.fid-ladder-rows{max-height:170px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#262E40 transparent}
.fid-ladder-row{height:16px;cursor:pointer;border-left:2px solid transparent}
.fid-ladder-row:nth-child(even){background:#0F131B}
.fid-ladder-row:hover{background:#151B27}
.fid-ladder-row[aria-selected="true"]{background:#1A2130;border-left-color:var(--fl-acc)}
.fid-ladder-row[aria-selected="true"] .fid-ladder-yr{color:var(--fl-acc)}
.fid-ladder-yr{color:var(--fl-dim)}
.fid-ladder-trk{display:flex;height:9px;background:#131824;border-radius:1px;overflow:hidden}
.fid-ladder-trk span{display:block;height:100%;transition:width .35s ease}
.fid-ladder-trk span+span{box-shadow:inset 1px 0 0 #0D1017}
.fid-ladder-s-g{background:var(--fl-g)}
.fid-ladder-s-a{background:var(--fl-a)}
.fid-ladder-s-b{background:var(--fl-b)}
.fid-ladder-amt,.fid-ladder-pct{text-align:right}
.fid-ladder-pct{color:var(--fl-dim)}
.fid-ladder-det{min-height:46px;padding:4px 8px;border-top:1px solid var(--fl-ln);background:#0A0D13}
.fid-ladder-dl{display:grid;grid-template-columns:1fr 34px 36px 38px;gap:6px;padding:1px 0}
.fid-ladder-dl span:nth-child(n+2){text-align:right}
.fid-ladder-dl span:first-child{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fid-ladder-dh{color:var(--fl-mut);font-size:8.5px;letter-spacing:.06em}
.fid-ladder-tag{display:inline-block;width:6px;height:6px;margin-right:4px;border-radius:1px}
.fid-ladder-kpi{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--fl-ln)}
.fid-ladder-kpi div{padding:4px 6px;border-right:1px solid #141925;min-width:0}
.fid-ladder-kpi div:last-child{border-right:0}
.fid-ladder-kpi span{display:block;color:var(--fl-mut);font-size:8.5px;letter-spacing:.05em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fid-ladder-kpi b{display:block;font-weight:600;font-size:10.5px;text-align:right;white-space:nowrap}
.fid-ladder-kpi small{font-size:8.5px;font-weight:400;color:var(--fl-dim)}
.fid-ladder-ft{padding:3px 8px;border-top:1px solid var(--fl-ln);color:var(--fl-mut);font-size:9px}
.fid-ladder-ft kbd{font:inherit;color:var(--fl-dim);border:1px solid #262E40;border-radius:2px;padding:0 3px;margin-right:1px}
@media (prefers-reduced-motion: reduce){
.fid-ladder .fid-ladder-trk span{transition:none}
}

js:
var SET = Date.UTC(2026, 8, 25), Y0 = 2027, Y1 = 2036;
var GRP = { G: { k: 'g', lbl: 'GOVT' }, A: { k: 'a', lbl: 'AA–A' }, B: { k: 'b', lbl: 'BBB' } };
/* desc, group, rating, coupon %, maturity, par USD mm */
var H = [
  ['UST 3.875 03/31/27', 'G', 'AA+', 3.875, '2027-03-31', 12.5], ['PG 2.800 03/25/27', 'A', 'AA-', 2.8, '2027-03-25', 7.5],
  ['UST 4.125 07/31/28', 'G', 'AA+', 4.125, '2028-07-31', 15.0], ['AAPL 4.000 05/10/28', 'A', 'AA+', 4.0, '2028-05-10', 10.0],
  ['JPM 4.505 10/22/29', 'A', 'A', 4.505, '2029-10-22', 12.5], ['CMCSA 4.150 10/15/29', 'A', 'A-', 4.15, '2029-10-15', 7.5],
  ['VZ 4.016 12/03/29', 'B', 'BBB+', 4.016, '2029-12-03', 10.0], ['UST 4.000 02/28/30', 'G', 'AA+', 4.0, '2030-02-28', 15.0],
  ['ORCL 2.950 04/01/30', 'B', 'BBB', 2.95, '2030-04-01', 12.5], ['BAC 4.570 04/27/31', 'A', 'A-', 4.57, '2031-04-27', 12.5],
  ['HD 4.850 06/25/31', 'A', 'A', 4.85, '2031-06-25', 10.0], ['CVS 5.250 01/30/31', 'B', 'BBB', 5.25, '2031-01-30', 10.0],
  ['UST 4.125 11/15/32', 'G', 'AA+', 4.125, '2032-11-15', 15.0], ['AMGN 4.200 03/01/32', 'B', 'BBB+', 4.2, '2032-03-01', 10.0],
  ['GS 5.050 07/23/33', 'B', 'BBB+', 5.05, '2033-07-23', 12.5], ['KO 4.650 08/14/33', 'A', 'A+', 4.65, '2033-08-14', 10.0],
  ['UST 4.000 02/15/34', 'G', 'AA+', 4.0, '2034-02-15', 17.5], ['WMT 4.100 04/15/34', 'A', 'AA', 4.1, '2034-04-15', 12.5],
  ['T 4.500 05/15/35', 'B', 'BBB', 4.5, '2035-05-15', 10.0], ['UNH 5.150 07/15/35', 'A', 'A+', 5.15, '2035-07-15', 7.5],
  ['UST 4.250 08/15/36', 'G', 'AA+', 4.25, '2036-08-15', 12.5], ['PEP 4.800 07/17/36', 'A', 'A+', 4.8, '2036-07-17', 7.5]
].map(function (r) {
  var p = r[4].split('-').map(Number);
  return { d: r[0], g: r[1], rt: r[2], c: r[3], y: p[0], m: p[1], dd: p[2], t: Date.UTC(p[0], p[1] - 1, p[2]), par: r[5] };
});
function dim(y, m) { return new Date(Date.UTC(y, m, 0)).getUTCDate(); }
/* semi-annual coupon dates anchored on the maturity day, end-of-month clamped */
function coupons(b) {
  var out = [];
  for (var j = 0; ; j++) {
    var mm = b.m - 6 * j, yy = b.y + Math.floor((mm - 1) / 12); mm = ((mm - 1) % 12 + 12) % 12 + 1;
    var t = Date.UTC(yy, mm - 1, Math.min(b.dd, dim(yy, mm)));
    if (t <= SET) break; out.push({ y: yy, amt: b.par * b.c / 200 });
  }
  return out;
}
var years = [];
for (var y = Y0; y <= Y1; y++) years.push({ y: y, bonds: [], par: { G: 0, A: 0, B: 0 }, cf: { G: 0, A: 0, B: 0 } });
H.forEach(function (b) {
  var r = years[b.y - Y0]; r.bonds.push(b); r.par[b.g] += b.par; r.cf[b.g] += b.par;
  coupons(b).forEach(function (c) { if (c.y >= Y0 && c.y <= Y1) years[c.y - Y0].cf[b.g] += c.amt; });
});
function tot(o) { return o.G + o.A + o.B; }
/* largest-remainder rounding so displayed % always foot to 100.0 */
function pcts(vals) {
  var s = vals.reduce(function (a, b) { return a + b; }, 0), raw = vals.map(function (v) { return v / s * 1000; });
  var fl = raw.map(Math.floor), left = 1000 - fl.reduce(function (a, b) { return a + b; }, 0);
  raw.map(function (v, i) { return [v - fl[i], i]; }).sort(function (a, b) { return b[0] - a[0]; })
    .slice(0, left).forEach(function (p) { fl[p[1]]++; });
  return fl.map(function (u) { return (u / 10).toFixed(1); });
}
function f1(x) { return x.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
var view = 'par', sel = 0;
var rowsEl = root.querySelector('.fid-ladder-rows'), detEl = root.querySelector('.fid-ladder-det'),
    kpiEl = root.querySelector('.fid-ladder-kpi'), lgEl = root.querySelector('.fid-ladder-lg');
var totPar = H.reduce(function (a, b) { return a + b.par; }, 0);
var gPar = { G: 0, A: 0, B: 0 }; H.forEach(function (b) { gPar[b.g] += b.par; });
var gp = pcts([gPar.G, gPar.A, gPar.B]);
lgEl.innerHTML = ['G', 'A', 'B'].map(function (g, i) {
  return '<span><i class="fid-ladder-s-' + GRP[g].k + '"></i>' + GRP[g].lbl + ' ' + gp[i] + '%</span>';
}).join('');
function draw() {
  var data = years.map(function (r) { return view === 'par' ? r.par : r.cf; });
  var totals = data.map(tot), max = Math.max.apply(null, totals), pc = pcts(totals);
  rowsEl.innerHTML = years.map(function (r, i) {
    var o = data[i], segs = ['G', 'A', 'B'].map(function (g) {
      return o[g] > 0 ? '<span class="fid-ladder-s-' + GRP[g].k + '" style="width:' + (o[g] / max * 100).toFixed(2) + '%" title="' + GRP[g].lbl + ' ' + o[g].toFixed(3) + '"></span>' : '';
    }).join('');
    return '<div class="fid-ladder-row" role="option" data-i="' + i + '" aria-selected="' + (i === sel) + '"><span class="fid-ladder-yr">' + r.y +
      '</span><span class="fid-ladder-trk">' + segs + '</span><span class="fid-ladder-amt">' + f1(totals[i]) + '</span><span class="fid-ladder-pct">' + pc[i] + '%</span></div>';
  }).join('');
  var grand = totals.reduce(function (a, b) { return a + b; }, 0);
  var wam = H.reduce(function (a, b) { return a + b.par * (b.t - SET) / 864e5 / 365.25; }, 0) / totPar;
  var wc = H.reduce(function (a, b) { return a + b.par * b.c; }, 0) / totPar;
  var roll = H.filter(function (b) { return b.t <= Date.UTC(2027, 8, 25); }).reduce(function (a, b) { return a + b.par; }, 0);
  kpiEl.innerHTML = '<div><span>' + (view === 'par' ? 'TOTAL PAR' : 'CF 2027–36') + '</span><b>' + f1(grand) + '</b></div>' +
    '<div><span>WAM</span><b>' + wam.toFixed(2) + 'y</b></div><div><span>W.AVG CPN</span><b>' + wc.toFixed(3) + '%</b></div>' +
    '<div><span>ROLL 12M</span><b>' + f1(roll) + ' <small>' + (roll / totPar * 100).toFixed(1) + '%</small></b></div>';
  detail();
}
function detail() {
  var r = years[sel];
  var head = '<div class="fid-ladder-dl fid-ladder-dh"><span>' + r.y + ' RUNG · ' + r.bonds.length + ' LINES</span><span>RTG</span><span>PAR</span><span>YRS</span></div>';
  detEl.innerHTML = head + r.bonds.map(function (b) {
    return '<div class="fid-ladder-dl"><span><i class="fid-ladder-tag fid-ladder-s-' + GRP[b.g].k + '"></i>' + b.d + '</span><span>' + b.rt +
      '</span><span>' + b.par.toFixed(1) + '</span><span>' + ((b.t - SET) / 864e5 / 365.25).toFixed(2) + '</span></div>';
  }).join('');
  var row = rowsEl.children[sel];
  if (row) {
    var top = row.offsetTop - rowsEl.offsetTop;
    if (top < rowsEl.scrollTop) rowsEl.scrollTop = top;
    else if (top + row.offsetHeight > rowsEl.scrollTop + rowsEl.clientHeight) rowsEl.scrollTop = top + row.offsetHeight - rowsEl.clientHeight;
  }
}
function select(i) {
  sel = Math.max(0, Math.min(years.length - 1, i));
  Array.prototype.forEach.call(rowsEl.children, function (el, j) { el.setAttribute('aria-selected', String(j === sel)); });
  detail();
}
function setView(v) {
  view = v;
  root.querySelectorAll('.fid-ladder-tabs button').forEach(function (b) { b.setAttribute('aria-selected', String(b.getAttribute('data-v') === v)); });
  draw();
}
rowsEl.addEventListener('click', function (e) { var r = e.target.closest('.fid-ladder-row'); if (r) { select(+r.getAttribute('data-i')); root.focus(); } });
root.querySelector('.fid-ladder-tabs').addEventListener('click', function (e) { var b = e.target.closest('button'); if (b) setView(b.getAttribute('data-v')); });
root.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowDown') { e.preventDefault(); select(sel + 1); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); select(sel - 1); }
  else if (e.key === 'Home') { e.preventDefault(); select(0); }
  else if (e.key === 'End') { e.preventDefault(); select(years.length - 1); }
  else if (e.key === 'c' || e.key === 'C') { e.preventDefault(); setView(view === 'par' ? 'cf' : 'par'); }
});
draw();

