.fid-spread-mon *{box-sizing:border-box}
.fid-spread-mon:focus-visible{box-shadow:0 0 0 1px var(--fs-acc)}
.fid-spread-mon-hd{display:flex;justify-content:space-between;align-items:center;padding:6px 8px 4px;background:linear-gradient(#141925,#0D1017)}
