.fid-spread-mon-th button{all:unset;cursor:pointer;text-align:right;color:inherit;white-space:nowrap}
.fid-spread-mon-th button:first-child{text-align:left}
.fid-spread-mon-th button[aria-pressed="true"]{color:var(--fs-acc)}
