.fid-spread-mon-rng:before{content:"";position:absolute;left:0;right:0;top:3px;height:1px;background:#2B3345}
.fid-spread-mon-rng b{position:absolute;top:0;width:3px;height:7px;margin-left:-1px;background:var(--fs-tx);border-radius:1px}
