@keyframes fid-spread-mon-ft{from{background:rgba(53,201,138,.4)}to{background:transparent}}
@media (prefers-reduced-motion: reduce){
.fid-spread-mon .fid-spread-mon-live i{animation:none}
.fid-spread-mon .fid-spread-mon-fw,.fid-spread-mon .fid-spread-mon-ft2{animation:none}
