js:
/* issue, coupon/maturity, rating, benchmark bucket, OAS now, prior close, 20D mean, 20D sd, trend (bp/day) */
var RAW = [
  ['AAPL', '4.300 05/10/33', 'AA+', 'A', 47, 46, 46.2, 1.4, 0], ['MSFT', '3.450 08/08/36', 'AAA', 'A', 44, 44, 44.6, 1.1, 0],
  ['JPM', '5.350 06/01/34', 'A', 'A', 93, 90, 89.8, 2.1, 0.1], ['BAC', '5.468 01/23/35', 'A-', 'A', 98, 96, 96.4, 1.9, 0],
  ['CMCSA', '4.950 10/15/33', 'A-', 'A', 94, 95, 95.9, 1.6, 0], ['GS', '5.851 04/25/35', 'BBB+', 'BBB', 104, 100, 99.6, 2.0, 0.1],
  ['VZ', '4.780 02/15/35', 'BBB+', 'BBB', 112, 113, 112.4, 1.8, 0], ['T', '5.400 02/15/34', 'BBB', 'BBB', 116, 114, 115.1, 2.2, 0],
  ['ORCL', '5.550 02/06/33', 'BBB', 'BBB', 134, 128, 124.5, 3.6, 0.5], ['CVS', '5.700 06/01/34', 'BBB', 'BBB', 141, 139, 140.2, 2.4, 0],
  ['BA', '6.528 05/01/34', 'BBB-', 'BBB', 158, 163, 166.8, 3.1, -0.4], ['F', '6.050 11/05/31', 'BBB-', 'BBB', 196, 194, 193.0, 3.4, 0]
];
var IDX = { IG: { v: 0, p: 0 }, A: { v: 71, p: 70 }, BBB: { v: 108, p: 107 } };
/* IG headline is the market-value blend of its buckets: 45% A-and-above, 55% BBB */
function blend() { IDX.IG.v = Math.round(0.45 * IDX.A.v + 0.55 * IDX.BBB.v); IDX.IG.p = Math.round(0.45 * IDX.A.p + 0.55 * IDX.BBB.p); }
blend();
var seed = 20260924;
function rnd() { seed |= 0; seed = seed + 0x6D2B79F5 | 0; var t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }
function gauss() { var u = 1 - rnd(), v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); }
var rows = RAW.map(function (r, i) {
  /* 20 prior closes ending at yesterday's close: an AR(1) path with trend, scaled so the
     window has the target mean and sd; the stats below are then measured on the rounded path */
  var x = [], e = 0, pc = r[5], MU = r[6], SD = r[7];
  for (var k = 0; k < 19; k++) { e = 0.6 * e + gauss(); x.push(e + r[8] * k / 0.8); }
  var m = x.reduce(function (a, b) { return a + b; }, 0) / 19, v = Math.sqrt(x.reduce(function (a, b) { return a + (b - m) * (b - m); }, 0) / 18);
  x = x.map(function (q) { return (q - m) / v; });
  var a = (20 * MU - pc) / 19, b = Math.sqrt(Math.max(0.01, (19 * SD * SD - (pc - MU) * (pc - MU) * 20 / 19) / 18));
  var h = x.map(function (q) { return Math.round((a + b * q) * 10) / 10; }).concat(pc);
  var mu = h.reduce(function (a, b) { return a + b; }, 0) / h.length;
  var sd = Math.sqrt(h.reduce(function (a, b) { return a + (b - mu) * (b - mu); }, 0) / (h.length - 1));
  return { i: i, tk: r[0], ds: r[1], rt: r[2], bk: r[3], oas: r[4], pc: r[5], h: h, mu: mu, sd: sd,
           lo: Math.min.apply(null, h), hi: Math.max.apply(null, h) };
});
function z(r) { return (r.oas - r.mu) / r.sd; }
function rel(r) { return r.oas - IDX[r.bk].v; }
function sg(x, d) { return (x > 0 ? '+' : x < 0 ? '−' : '±') + Math.abs(x).toFixed(d || 0); }
var body = root.querySelector('.fid-spread-mon-body'), rd = root.querySelector('.fid-spread-mon-rd'), idxEl = root.querySelector('.fid-spread-mon-idx');
var SORTS = ['oas', 'd', 'rel', 'z', 'tk'], sortKey = 'oas', order = rows.slice(), sel = rows[8];
var KEYF = { tk: function (r) { return r.tk; }, oas: function (r) { return r.oas; }, d: function (r) { return -(r.oas - r.pc); },
             rel: function (r) { return -rel(r); }, z: function (r) { return -z(r); } };
function sortRows() {
  var f = KEYF[sortKey];
  order = rows.slice().sort(function (a, b) { var x = f(a), y = f(b); return x < y ? -1 : x > y ? 1 : a.i - b.i; });
  root.querySelectorAll('.fid-spread-mon-th button').forEach(function (b) { b.setAttribute('aria-pressed', String(b.getAttribute('data-s') === sortKey)); });
}
function dirCls(d) { return d > 0 ? 'fid-spread-mon-w' : d < 0 ? 'fid-spread-mon-n' : ''; }
function arrow(d) { return d > 0 ? '▲' : d < 0 ? '▼' : ' '; }
function cells(r) {
  var d = r.oas - r.pc, zz = z(r), lo = Math.min(r.lo, r.oas), hi = Math.max(r.hi, r.oas), span = Math.max(hi - lo, 1);
  var brk = Math.abs(zz) >= 2;
  return '<span class="fid-spread-mon-tk">' + r.tk + ' <small>' + r.ds.slice(-2) + '</small></span>' +
    '<span>' + r.oas + '</span>' +
    '<span class="' + dirCls(d) + '">' + arrow(d) + sg(d) + '</span>' +
    '<span>' + sg(rel(r)) + '</span>' +
    '<span class="fid-spread-mon-rng" title="20D ' + lo.toFixed(1) + '–' + hi.toFixed(1) + '"><u style="left:' + ((r.mu - lo) / span * 100).toFixed(1) + '%"></u><b style="left:' + ((r.oas - lo) / span * 100).toFixed(1) + '%"></b></span>' +
    '<span class="fid-spread-mon-z' + (brk ? ' fid-spread-mon-brk' : '') + '">' + (brk ? '⚑' : '') + sg(zz, 1) + '</span>';
}
function drawIdx() {
  idxEl.innerHTML = ['IG', 'A', 'BBB'].map(function (k) {
    var d = IDX[k].v - IDX[k].p;
    return '<div><span>' + k + '</span><b>' + IDX[k].v + ' <em class="' + dirCls(d) + '">' + arrow(d) + sg(d) + '</em></b></div>';
  }).join('');
}
function draw() {
  body.innerHTML = order.map(function (r) {
    return '<div class="fid-spread-mon-row" role="option" data-i="' + r.i + '" aria-selected="' + (r === sel) + '">' + cells(r) + '</div>';
  }).join('');
  readout();
}
function readout() {
  var r = sel, d = r.oas - r.pc, zz = z(r);
  rd.innerHTML = '<b>' + r.tk + ' ' + r.ds + '</b> · ' + r.rt + ' · OAS <b>' + r.oas + 'bp</b> ' +
    '<span class="' + dirCls(d) + '">' + arrow(d) + sg(d) + ' ' + (d > 0 ? 'wider' : d < 0 ? 'tighter' : 'unch') + '</span><br>' +
    sg(rel(r)) + 'bp vs ' + r.bk + ' IDX ' + IDX[r.bk].v + ' · 20D μ ' + r.mu.toFixed(1) + ' σ ' + r.sd.toFixed(1) +
    ' → Z <b>' + sg(zz, 2) + '</b>' + (Math.abs(zz) >= 2 ? ' <span class="fid-spread-mon-z fid-spread-mon-brk">⚑ BREACH</span>' : ' within band');
}
function select(r) {
  sel = r;
  Array.prototype.forEach.call(body.children, function (el) { el.setAttribute('aria-selected', String(+el.getAttribute('data-i') === r.i)); });
  var el = body.querySelector('[data-i="' + r.i + '"]');
  if (el) {
    var top = el.offsetTop - body.offsetTop;
    if (top < body.scrollTop) body.scrollTop = top;
    else if (top + el.offsetHeight > body.scrollTop + body.clientHeight) body.scrollTop = top + el.offsetHeight - body.clientHeight;
  }
  readout();
}
function tickRow(r, dv) {
  r.oas += dv;
  var el = body.querySelector('[data-i="' + r.i + '"]');
  if (!el) return;
  el.innerHTML = cells(r);
  if (dv) el.children[1].classList.add(dv > 0 ? 'fid-spread-mon-fw' : 'fid-spread-mon-ft2');
}
root.querySelector('.fid-spread-mon-th').addEventListener('click', function (e) {
  var b = e.target.closest('button'); if (!b) return; sortKey = b.getAttribute('data-s'); sortRows(); draw();
});
body.addEventListener('click', function (e) { var el = e.target.closest('.fid-spread-mon-row'); if (el) { select(rows[+el.getAttribute('data-i')]); root.focus(); } });
root.addEventListener('keydown', function (e) {
  var k = order.indexOf(sel);
  if (e.key === 'ArrowDown') { e.preventDefault(); select(order[Math.min(order.length - 1, k + 1)]); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); select(order[Math.max(0, k - 1)]); }
  else if (e.key === 's' || e.key === 'S') { e.preventDefault(); sortKey = SORTS[(SORTS.indexOf(sortKey) + 1) % SORTS.length]; sortRows(); draw(); }
});
sortRows(); drawIdx(); draw();
var timer = setInterval(function () {
  if (!root.isConnected) { clearInterval(timer); return; }
  var r = rows[Math.floor(rnd() * rows.length)];
  /* mean-revert gently toward the prior close so the tape never drifts off */
  var p = 0.5 + Math.max(-0.3, Math.min(0.3, (r.pc - r.oas) * 0.06)), dv = rnd() < p ? 1 : -1;
  tickRow(r, dv);
  if (rnd() < 0.08) {
    var k = rnd() < 0.5 ? 'A' : 'BBB', m = rnd() < 0.5 ? 1 : -1;
    if (Math.abs(IDX[k].v + m - IDX[k].p) <= 3) { IDX[k].v += m; blend(); drawIdx(); order.forEach(function (x) { if (x.bk === k) tickRow(x, 0); }); }
  }
  if (r === sel || rnd() < 0.1) readout();
}, 1300);

