var R = ['AAA', 'AA', 'A', 'BBB', 'BB', 'B', 'CCC'], COLS = R.concat('D');
/* one-year transition probabilities, % of issuers (rows foot to 100.00) */
var M1 = [
  [89.60, 9.25, 0.82, 0.18, 0.08, 0.04, 0.03, 0.00],
  [0.52, 89.94, 8.61, 0.61, 0.13, 0.10, 0.05, 0.04],
  [0.04, 1.71, 91.62, 5.81, 0.52, 0.18, 0.04, 0.08],
  [0.01, 0.11, 3.72, 91.18, 3.94, 0.58, 0.20, 0.26],
  [0.01, 0.04, 0.18, 5.58, 84.42, 7.95, 0.93, 0.89],
  [0.00, 0.03, 0.10, 0.22, 5.49, 84.03, 6.07, 4.06],
  [0.00, 0.00, 0.14, 0.21, 0.72, 14.36, 45.82, 38.75]
];
var BOOK = [38.0, 96.4, 305.2, 412.6, 58.3, 21.7, 4.1], LGD = 0.60;   /* USD mm market value by rating; 40% recovery */
/* Markov chain: add D as an absorbing state and raise the 8x8 matrix to the horizon */
function sq(M) { return M.map(function (r) { return r.slice(); }).concat([[0, 0, 0, 0, 0, 0, 0, 100]]); }
function mul(A, B) {
  return A.map(function (row) { return B[0].map(function (_, j) { var s = 0; for (var k = 0; k < 8; k++) s += row[k] * B[k][j] / 100; return s; }); });
}
var A1 = sq(M1), A3 = mul(mul(A1, A1), A1);
/* largest-remainder rounding to 0.01 so every displayed row foots to exactly 100.00 */
function footRow(row) {
  var raw = row.map(function (v) { return v * 100; }), fl = raw.map(Math.floor);
  var left = 10000 - fl.reduce(function (a, b) { return a + b; }, 0);
  raw.map(function (v, i) { return [v - fl[i], i]; }).sort(function (a, b) { return b[0] - a[0]; }).slice(0, left).forEach(function (p) { fl[p[1]]++; });
  return fl.map(function (u) { return u / 100; });
}
var H = { 1: A1.slice(0, 7).map(footRow), 3: A3.slice(0, 7).map(footRow) };
var hz = 1, cr = 3, cc = 4;
var thead = root.querySelector('thead'), tbody = root.querySelector('tbody'), rd = root.querySelector('.fid-ratings-mig-rd'), bk = root.querySelector('.fid-ratings-mig-bk');
function shade(v, i, j) {
  if (v <= 0) return 'transparent';
  var a = Math.min(1, Math.log(1 + v * 10) / Math.log(1001));
  if (i === j) return 'rgba(90,120,170,' + (0.12 + a * 0.45).toFixed(3) + ')';
  if (j === 7) return 'rgba(200,40,60,' + (0.1 + a * 0.75).toFixed(3) + ')';
  return j < i ? 'rgba(53,201,138,' + (0.06 + a * 0.6).toFixed(3) + ')' : 'rgba(242,95,107,' + (0.06 + a * 0.6).toFixed(3) + ')';
}
function draw() {
  var P = H[hz];
  thead.innerHTML = '<tr><th scope="col">FROM<br>↓ TO→</th>' + COLS.map(function (c, j) { return '<th scope="col"' + (j === cc ? ' class="fid-ratings-mig-hl"' : '') + '>' + c + '</th>'; }).join('') + '</tr>';
  tbody.innerHTML = P.map(function (row, i) {
    return '<tr><th scope="row"' + (i === cr ? ' class="fid-ratings-mig-hl"' : '') + '>' + R[i] + '</th>' + row.map(function (v, j) {
      var raw = hz === 1 ? M1[i][j] : A3[i][j], cls = [];
      if (i === j) cls.push('fid-ratings-mig-dg');
      if (raw === 0) cls.push('fid-ratings-mig-z');
      if (i === cr && j === cc) cls.push('fid-ratings-mig-sel');
      return '<td role="gridcell" data-r="' + i + '" data-c="' + j + '" class="' + cls.join(' ') + '" style="background:' + shade(v, i, j) + '">' + (raw === 0 ? '·' : v.toFixed(2)) + '</td>';
    }).join('') + '</tr>';
  }).join('');
  readout();
}
function kind(i, j) {
  if (j === 7) return ['d', '✖ DEFAULT', ''];
  if (i === j) return ['m', '■ STABLE', ''];
  var n = Math.abs(i - j), up = j < i, ig = function (k) { return k <= 3; };
  var tag = !up && ig(i) && !ig(j) ? 'FALLEN ANGEL' : up && !ig(i) && ig(j) ? 'RISING STAR' : '';
  return [up ? 'u' : 'd', (up ? '▲ ' : '▼ ') + n + '-CAT ' + (up ? 'UPGRADE' : 'DOWNGRADE'), tag];
}
function fm(x) { return x.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function readout() {
  var P = H[hz], row = P[cr], v = row[cc], k = kind(cr, cc);
  var up = 0, dn = 0, st = row[cr], d = row[7], hy = 0;
  for (var j = 0; j < 7; j++) { if (j < cr) up += row[j]; if (j > cr) dn += row[j]; if (j > 3) hy += row[j]; }
  var sum = up + st + dn + d;
  rd.innerHTML = '<b>' + R[cr] + ' → ' + COLS[cc] + '</b> <b>' + v.toFixed(2) + '%</b> <span class="fid-ratings-mig-' + k[0] + '">' + k[1] +
    (k[2] ? '<span class="fid-ratings-mig-tag">' + k[2] + '</span>' : '') + '</span> <span class="fid-ratings-mig-m">' + hz + 'Y</span><br>' +
    '<span class="fid-ratings-mig-u">▲' + up.toFixed(2) + '</span> · <span class="fid-ratings-mig-m">■' + st.toFixed(2) + '</span> · ' +
    '<span class="fid-ratings-mig-d">▼' + dn.toFixed(2) + '</span> · <span class="fid-ratings-mig-d">✖' + d.toFixed(2) + '</span> ' +
    '<span class="fid-ratings-mig-m">Σ ' + sum.toFixed(2) + '</span>';
  var E = BOOK[cr], ig = cr <= 3;
  var migr = ig ? E * hy / 100 : E * dn / 100, el = 0, tot = 0;
  BOOK.forEach(function (e, i) { tot += e; el += e * P[i][7] / 100 * LGD; });
  bk.innerHTML = '<div><span>BOOK ' + R[cr] + ' MV</span><b>$' + fm(E) + 'mm</b></div>' +
    '<div><span>' + (ig ? 'EXP. → HY' : 'EXP. DOWNGRADE') + ' ' + hz + 'Y</span><b>$' + fm(migr) + 'mm</b></div>' +
    '<div><span>BOOK EL ' + hz + 'Y @40% REC</span><b>$' + fm(el) + 'mm</b></div>';
  bk.title = 'Expected loss = Σ MV × PD(' + hz + 'Y) × LGD 60% over book $' + fm(tot) + 'mm = ' + (el / tot * 1e4).toFixed(1) + 'bp';
}
function setH(h) {
  hz = h;
  root.querySelectorAll('.fid-ratings-mig-tabs button').forEach(function (b) { b.setAttribute('aria-selected', String(+b.getAttribute('data-h') === h)); });
  draw();
}
root.querySelector('.fid-ratings-mig-tabs').addEventListener('click', function (e) { var b = e.target.closest('button'); if (b) setH(+b.getAttribute('data-h')); });
tbody.addEventListener('click', function (e) {
  var td = e.target.closest('td'); if (!td) return;
  cr = +td.getAttribute('data-r'); cc = +td.getAttribute('data-c'); draw(); root.focus();
});
root.addEventListener('keydown', function (e) {
  var k = e.key, hit = true;
  if (k === 'ArrowUp') cr = Math.max(0, cr - 1);
  else if (k === 'ArrowDown') cr = Math.min(6, cr + 1);
  else if (k === 'ArrowLeft') cc = Math.max(0, cc - 1);
  else if (k === 'ArrowRight') cc = Math.min(7, cc + 1);
  else if (k === 'Home') cc = 0;
  else if (k === 'End') cc = 7;
  else if (k === '1' || k === '3') { e.preventDefault(); setH(+k); return; }
  else hit = false;
  if (hit) { e.preventDefault(); draw(); }
});
draw();

