.fid-cashflow{--fc-bg:#0D1017;--fc-ln:#1D2331;--fc-tx:#D5DBE7;--fc-dim:#7A8499;--fc-mut:#4D566A;--fc-acc:#F2A93B;--fc-inf:#5AA9FF;--fc-up:#35C98A;box-sizing:border-box;width:100%;min-width:260px;background:var(--fc-bg);border:1px solid var(--fc-ln);border-radius:4px;color:var(--fc-tx);font:10px/1.35 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;overflow:hidden;outline:none}
