.fid-cashflow-th,.fid-cashflow-r,.fid-cashflow-tot{display:grid;grid-template-columns:minmax(54px,.9fr) minmax(72px,1.2fr) minmax(44px,.7fr) minmax(72px,1.2fr);gap:5px;padding:0 8px;min-width:258px;font-size:9px;align-items:center}
