.fid-cashflow-r.fid-cashflow-paid .fid-cashflow-ok{color:#2E7F5B}
.fid-cashflow-r.fid-cashflow-next span:first-child{color:var(--fc-acc)}
.fid-cashflow-r.fid-cashflow-red{background:#121A14}
.fid-cashflow-r em{font-style:normal;color:var(--fc-acc)}
.fid-cashflow-p{color:var(--fc-inf);font-weight:700}
.fid-cashflow-pv{background:linear-gradient(90deg,transparent calc(100% - var(--fc-w)),rgba(90,169,255,.2) calc(100% - var(--fc-w)));border-radius:1px}
.fid-cashflow-tot{height:17px;white-space:nowrap;border-top:1px solid #2B3345;font-weight:700;background:#10141D}
.fid-cashflow-tot span:first-child{color:var(--fc-dim);font-weight:400;white-space:nowrap;overflow:hidden}
.fid-cashflow-sum{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));border-top:1px solid var(--fc-ln)}
