.fid-cashflow-sum div{border-right:1px solid #141925}
.fid-cashflow-sum span{color:var(--fc-dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fid-cashflow-sum b{font-weight:400;white-space:nowrap}
.fid-cashflow-sum .fid-cashflow-k{color:var(--fc-acc);font-weight:700}
.fid-cashflow-ft{padding:3px 8px;color:var(--fc-mut);font-size:8.5px;background:#0A0D13;line-height:1.5}
.fid-cashflow-ft kbd{font:inherit;color:var(--fc-dim);border:1px solid #262E40;border-radius:2px;padding:0 3px}
