@keyframes fid-cashflow-flash{from{background-color:rgba(242,169,59,.28)}to{background-color:transparent}}
@media (prefers-reduced-motion: reduce){
.fid-cashflow .fid-cashflow-flash{animation:none}
}

js:
var CPN = 5.125, MY = 2031, MM = 11, MD = 1, SET = Date.UTC(2026, 8, 25), FREQ = 2;
var face = 10000000, Y = 0.0548;
var MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function ymd(t) { var d = new Date(t); return [d.getUTCFullYear(), d.getUTCMonth() + 1, d.getUTCDate()]; }
function d360(a, b) { var x = ymd(a), z = ymd(b), d1 = Math.min(x[2], 30), d2 = z[2]; if (d2 === 31 && d1 === 30) d2 = 30; return 360 * (z[0] - x[0]) + 30 * (z[1] - x[1]) + (d2 - d1); }
function dim(y, m) { return new Date(Date.UTC(y, m, 0)).getUTCDate(); }
function back(j) { var m = MM - 6 * j, y = MY + Math.floor((m - 1) / 12); m = ((m - 1) % 12 + 12) % 12 + 1; return Date.UTC(y, m - 1, Math.min(MD, dim(y, m))); }
function roll(t) { var w = new Date(t).getUTCDay(); return w === 6 ? t + 2 * 864e5 : w === 0 ? t + 864e5 : t; }
function ds(t) { var d = ymd(t); return (d[2] < 10 ? '0' : '') + d[2] + '-' + MON[d[1] - 1] + '-' + String(d[0]).slice(2); }
function fm(x) { var s = Math.abs(x).toFixed(2).split('.'); s[0] = s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ','); return (x < 0 ? '−' : '') + s.join('.'); }
function r2(x) { return Math.round(x * 100) / 100; }
var dates = [], j = 0, PREV;
for (;; j++) { var t = back(j); if (t <= SET) { PREV = t; break; } dates.unshift(t); }
var N = dates.length, PER = 360 / FREQ, W = d360(SET, dates[0]) / PER, ACD = d360(PREV, SET);
var body = root.querySelector('.fid-cashflow-body'), tot = root.querySelector('.fid-cashflow-tot'), sum = root.querySelector('.fid-cashflow-sum');
var inp = { face: root.querySelector('[data-k="face"]'), y: root.querySelector('[data-k="y"]') };
function render() {
  var cpnAmt = r2(face * CPN / 100 / FREQ), v = 1 / (1 + Y / FREQ), rows = [], sCF = 0, sPV = 0, sT = 0;
  for (var k = 1; k <= N; k++) {
    var tp = k - 1 + W, df = Math.pow(v, tp), legs = [[cpnAmt, false]];
    if (k === N) legs.push([face, true]);        /* redemption shown as its own leg on the maturity date */
    legs.forEach(function (lg) {
      var pv = r2(lg[0] * df);
      rows.push({ t: dates[k - 1], cf: lg[0], df: df, pv: pv, tp: tp, prin: lg[1] });
      sCF += lg[0]; sPV += pv; sT += tp / FREQ * pv;
    });
  }
  sCF = r2(sCF); sPV = r2(sPV);
  var ai = r2(cpnAmt * ACD / PER), clean = r2(sPV - ai), mac = sT / sPV, mod = mac / (1 + Y / FREQ);
  var h = '<div class="fid-cashflow-r fid-cashflow-paid"><span>' + ds(roll(PREV)) + '</span><span>' + fm(cpnAmt) + '</span><span class="fid-cashflow-ok">✓ PAID</span><span>—</span></div>';
  h += rows.map(function (r, i) {
    var adj = roll(r.t), cls = 'fid-cashflow-r' + (i === 0 ? ' fid-cashflow-next' : '') + (r.prin ? ' fid-cashflow-red' : '');
    return '<div class="' + cls + '" title="t = ' + (r.tp / FREQ).toFixed(4) + 'y · accrual date ' + ds(r.t) + '"><span>' +
      (r.prin ? '<b class="fid-cashflow-p">↳ PRIN</b>' : ds(adj) + (adj !== r.t ? '<em>†</em>' : '')) +
      '</span><span' + (r.prin ? ' class="fid-cashflow-p"' : '') + '>' + fm(r.cf) + '</span><span>' + r.df.toFixed(6) +
      '</span><span class="fid-cashflow-pv" style="--fc-w:' + (r.pv / sPV * 100).toFixed(1) + '%">' + fm(r.pv) + '</span></div>';
  }).join('');
  body.innerHTML = h;
  tot.innerHTML = '<span>Σ ' + rows.length + ' CF</span><span>' + fm(sCF) + '</span><span></span><span>' + fm(sPV) + '</span>';
  var cells = [
    ['Dirty MV = ΣPV', fm(sPV)], ['Accrued ' + ACD + '/' + PER + 'd', fm(ai)],
    ['Clean MV', fm(clean)], ['Clean px', (clean / face * 100).toFixed(4), 1],
    ['Dur mac / mod', mac.toFixed(3) + ' / ' + mod.toFixed(3)], ['DV01', '$' + fm(mod * sPV / 10000), 1]
  ];
  sum.innerHTML = cells.map(function (c) { return '<div><span>' + c[0] + '</span><b' + (c[2] ? ' class="fid-cashflow-k"' : '') + '>' + c[1] + '</b></div>'; }).join('');
  inp.face.value = (face / 1e6).toFixed(3);
  inp.y.value = (Y * 100).toFixed(4);
  inp.face.classList.remove('fid-cashflow-err'); inp.y.classList.remove('fid-cashflow-err');
}
function flash() { sum.classList.remove('fid-cashflow-flash'); void sum.offsetWidth; sum.classList.add('fid-cashflow-flash'); }
function apply(k, val) {
  var v = parseFloat(String(val).replace(/,/g, ''));
  if (!isFinite(v)) return false;
  if (k === 'face') { if (v <= 0 || v > 5000) return false; face = Math.round(v * 1000) * 1000; }
  else { if (v <= -2 || v >= 30) return false; Y = v / 100; }
  return true;
}
Object.keys(inp).forEach(function (k) {
  var el = inp[k];
  el.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
      e.preventDefault(); e.stopPropagation();
      var step = (k === 'face' ? 1 : 0.01) * (e.shiftKey ? 5 : 1) * (e.key === 'ArrowUp' ? 1 : -1);
      if (apply(k, (parseFloat(el.value) || 0) + step)) { render(); flash(); }
    } else if (e.key === 'Enter') {
      e.preventDefault(); e.stopPropagation();
      if (apply(k, el.value)) { render(); flash(); } else el.classList.add('fid-cashflow-err');
    } else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); render(); root.focus(); }
  });
  el.addEventListener('blur', render);
});
root.addEventListener('keydown', function (e) {
  if (e.target !== root) return;
  var m = { f: 'face', y: 'y' }[e.key.toLowerCase()];
  if (m) { e.preventDefault(); inp[m].focus(); inp[m].select(); }
});
render();

css:
.fid-new-issue{--fn-bg:#0D1017;--fn-ln:#1D2331;--fn-tx:#D5DBE7;--fn-dim:#7A8499;--fn-mut:#4D566A;--fn-acc:#F2A93B;--fn-up:#35C98A;--fn-dn:#F25F6B;--fn-inf:#5AA9FF;--fn-vio:#A98BFF;box-sizing:border-box;width:100%;min-width:260px;background:var(--fn-bg);border:1px solid var(--fn-ln);border-radius:4px;color:var(--fn-tx);font:10px/1.35 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;overflow:hidden;outline:none}
.fid-new-issue *{box-sizing:border-box}
.fid-new-issue:focus-visible{box-shadow:0 0 0 1px var(--fn-acc)}
.fid-new-issue-hd{display:flex;justify-content:space-between;align-items:baseline;gap:6px;padding:6px 8px 4px;background:linear-gradient(#141925,#0D1017)}
.fid-new-issue-t{white-space:nowrap;font:700 10.5px/1 system-ui,-apple-system,Segoe UI,sans-serif;letter-spacing:.1em;color:var(--fn-acc)}
.fid-new-issue-m{color:var(--fn-mut);font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fid-new-issue-kpi{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--fn-ln);border-bottom:1px solid var(--fn-ln)}
.fid-new-issue-kpi div{padding:2px 6px;border-right:1px solid #141925;min-width:0}
