.fid-new-issue-kpi span{display:block;color:var(--fn-mut);font-size:8px;letter-spacing:.05em;white-space:nowrap}
.fid-new-issue-kpi b{display:block;text-align:right;font-weight:600;font-size:10.5px;white-space:nowrap}
