.fid-new-issue-list{max-height:170px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#262E40 transparent}
.fid-new-issue-row{padding:3px 8px 3px 6px;border-left:2px solid transparent;border-bottom:1px solid #141925;cursor:pointer}
.fid-new-issue-row:hover{background:#131823}
.fid-new-issue-row[aria-selected="true"]{background:#1A2130;border-left-color:var(--fn-acc)}
.fid-new-issue-l1{display:flex;align-items:center;gap:6px;white-space:nowrap;overflow:hidden}
.fid-new-issue-tk{font-weight:700;color:#fff;min-width:46px}
.fid-new-issue-l1 small{color:var(--fn-dim);font-size:9px;overflow:hidden;text-overflow:ellipsis}
.fid-new-issue-sz{margin-left:auto;color:var(--fn-tx)}
.fid-new-issue-st{flex:none;font:600 8px/1 system-ui,-apple-system,Segoe UI,sans-serif;letter-spacing:.06em;padding:2px 4px;border-radius:2px;border:1px solid currentColor}
.fid-new-issue-st[data-s="ANNCD"]{color:var(--fn-dim)}
.fid-new-issue-st[data-s="IPTS"]{color:var(--fn-inf)}
.fid-new-issue-st[data-s="GUID"]{color:var(--fn-acc)}
.fid-new-issue-st[data-s="LAUNCH"]{color:var(--fn-vio)}
.fid-new-issue-st[data-s="PRICED"]{color:#0B1A12;background:var(--fn-up);border-color:var(--fn-up)}
.fid-new-issue-l2{margin-top:1px;color:var(--fn-dim)}
.fid-new-issue-l2 span:nth-child(n+2){text-align:right;color:var(--fn-tx)}
.fid-new-issue-path{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fid-new-issue-path b{color:var(--fn-tx);font-weight:600}
.fid-new-issue-path i{font-style:normal;color:var(--fn-mut)}
.fid-new-issue-bump{animation:fid-new-issue-bump .8s ease-out}
.fid-new-issue-det{padding:4px 8px 3px;border-top:1px solid var(--fn-ln);background:#0A0D13;min-height:62px}
.fid-new-issue-dt{display:flex;justify-content:space-between;gap:6px;color:var(--fn-dim);font-size:9px;white-space:nowrap;overflow:hidden}
.fid-new-issue-dt b{color:var(--fn-tx)}
.fid-new-issue-ax{position:relative;height:22px;margin:3px 4px 2px;border-bottom:1px solid #2B3345}
.fid-new-issue-ax span{position:absolute;bottom:-3px;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;font-size:8px;line-height:1;color:var(--fn-dim);white-space:nowrap}
.fid-new-issue-ax span:after{content:"";width:1px;height:6px;margin-top:2px;background:currentColor}
.fid-new-issue-ax .fid-new-issue-gr{position:absolute;bottom:-2px;height:4px;background:rgba(242,169,59,.35);border-radius:1px}
.fid-new-issue-ax .fid-new-issue-mk-l{color:var(--fn-vio)}
.fid-new-issue-ax .fid-new-issue-mk-f{color:var(--fn-up)}
.fid-new-issue-ax .fid-new-issue-mk-i{color:var(--fn-inf)}
.fid-new-issue-ds{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin-top:3px;font-size:9px}
.fid-new-issue-ds div{display:flex;flex-direction:column;min-width:0}
.fid-new-issue-ds span{color:var(--fn-mut);font-size:8px;white-space:nowrap}
.fid-new-issue-ds b{font-weight:600;text-align:right;white-space:nowrap}
.fid-new-issue-tkt{display:grid;grid-template-columns:82px 1fr;gap:6px;align-items:end;padding:4px 8px;border-top:1px solid var(--fn-ln)}
.fid-new-issue-tkt label{display:flex;flex-direction:column;gap:2px}
.fid-new-issue-tkt span{color:var(--fn-mut);font-size:8px;letter-spacing:.05em}
.fid-new-issue-tkt input{width:100%;background:#07090E;border:1px solid #262E40;border-radius:2px;color:#FFE3B0;font:700 11px/1 ui-monospace,Menlo,Consolas,monospace;text-align:right;padding:3px 5px;outline:none}
.fid-new-issue-tkt input:focus{border-color:var(--fn-acc);background:#16120A}
.fid-new-issue-msg{color:var(--fn-dim);font-size:9px;line-height:1.3;padding-bottom:2px}
.fid-new-issue-msg b{color:var(--fn-up);font-weight:600}
.fid-new-issue-msg em{font-style:normal;color:var(--fn-dn)}
.fid-new-issue-ft{padding:3px 8px;border-top:1px solid var(--fn-ln);color:var(--fn-mut);font-size:8.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fid-new-issue-ft kbd{font:inherit;color:var(--fn-dim);border:1px solid #262E40;border-radius:2px;padding:0 3px}
@keyframes fid-new-issue-bump{from{color:#0B1A12;background:var(--fn-up)}to{background:transparent}}
@media (prefers-reduced-motion: reduce){
.fid-new-issue .fid-new-issue-bump{animation:none}
}

