/* benchmark UST yields by tenor, % */
var BM = { '5Y': 3.781, '6NC5': 3.781, '7Y': 3.912, '10Y': 4.104, '30Y': 4.712 };
/* ipt / guidance [lo, hi] / launch are spreads in bp over the tenor benchmark; fv = fair value off the secondary curve */
var D = [
  { tk: 'ORNRL', nm: 'Orion Rail Corp', rt: 'A3/A-', ten: '10Y', size: 750, ipt: 135, g: [110, 120], l: 110, book: 3400, fv: 104, st: 'PRICED', note: 'Books closed 11:42 ET · allocs out' },
  { tk: 'VRDPH', nm: 'Veridian Pharma Inc', rt: 'A3/A', ten: '5Y', size: 1000, ipt: 90, g: [70, 76], l: 70, book: 3900, fv: 66, st: 'LAUNCH', note: 'Launched, pricing ~14:30 ET' },
  { tk: 'CSTLN', nm: 'Castellan Bank NA', rt: 'A2/BBB+', ten: '6NC5', size: 1250, ipt: 120, g: [97, 103], l: null, book: 4100, fv: 93, st: 'GUID', note: 'Books close 12:15 ET' },
  { tk: 'BRWTEL', nm: 'Brightwater Telecom', rt: 'Baa3/BBB-', ten: '10Y', size: 1250, ipt: 185, g: [160, 170], l: null, book: 5200, fv: 158, st: 'GUID', note: 'Books close 12:30 ET' },
  { tk: 'NWUTIL', nm: 'Northwind Utilities', rt: 'A3/BBB+', ten: '30Y', size: 500, ipt: 155, g: null, l: null, book: 1600, fv: 138, st: 'IPTS', note: 'IPTs 09:05 ET, guidance due 11:30' },
  { tk: 'HLCYN', nm: 'Halcyon REIT LP', rt: 'Baa2/BBB', ten: '7Y', size: 600, ipt: null, g: null, l: null, book: 0, fv: 128, st: 'ANNCD', note: 'Investor call 13:00 ET · exp. size' }
];
var LABEL = { ANNCD: 'ANNCD', IPTS: 'IPTs', GUID: 'GUID', LAUNCH: 'LAUNCH', PRICED: 'PRICED' };
var sel = 0, ioiN = 0;
var list = root.querySelector('.fid-new-issue-list'), det = root.querySelector('.fid-new-issue-det'),
    kpi = root.querySelector('.fid-new-issue-kpi'), msg = root.querySelector('.fid-new-issue-msg'), inp = root.querySelector('[data-k="ioi"]');
function cur(d) { return d.l != null ? d.l : d.g ? (d.g[0] + d.g[1]) / 2 : d.ipt; }
function sg(x, dp) { return (x > 0 ? '+' : x < 0 ? '−' : '±') + Math.abs(x).toFixed(dp || 0); }
function bn(mm) { return (mm / 1000).toFixed(2); }
function gtxt(d) { if (!d.g) return '–'; var m = (d.g[0] + d.g[1]) / 2, h = (d.g[1] - d.g[0]) / 2; return m + '±' + h; }
function path(d) {
  if (d.ipt == null) return '<i>no price talk</i>';
  return '<b>' + d.ipt + 'a</b> <i>›</i> ' + (d.g ? '<b>' + gtxt(d) + '</b>' : '<i>–</i>') + ' <i>›</i> ' + (d.l != null ? '<b>' + d.l + '</b>' : '<i>–</i>');
}
function rowHtml(d, i) {
  var c = cur(d), nic = c != null ? c - d.fv : null;
  return '<div class="fid-new-issue-row" role="option" data-i="' + i + '" aria-selected="' + (i === sel) + '">' +
    '<div class="fid-new-issue-l1"><span class="fid-new-issue-tk">' + d.tk + '</span><small>' + d.rt + ' · ' + d.ten + '</small>' +
    '<span class="fid-new-issue-sz">$' + d.size.toLocaleString('en-US') + 'mm</span><span class="fid-new-issue-st" data-s="' + d.st + '">' + LABEL[d.st] + '</span></div>' +
    '<div class="fid-new-issue-l2"><span class="fid-new-issue-path">' + path(d) + '</span><span data-f="book">' + (d.book ? bn(d.book) + 'bn' : '–') +
    '</span><span data-f="cov">' + (d.book ? (d.book / d.size).toFixed(2) + 'x' : '–') + '</span><span>' + (nic != null ? sg(nic, nic % 1 ? 1 : 0) : '–') + '</span></div></div>';
}
function drawKpi() {
  var sz = 0, bk = 0, live = 0;
  D.forEach(function (d) { sz += d.size; bk += d.book; if (d.st === 'IPTS' || d.st === 'GUID' || d.st === 'LAUNCH') live++; });
  var withBook = D.filter(function (d) { return d.book; }), wsz = withBook.reduce(function (a, d) { return a + d.size; }, 0);
  kpi.innerHTML = '<div><span>DEALS</span><b>' + D.length + ' / ' + live + ' live</b></div><div><span>SIZE</span><b>$' + bn(sz) + 'bn</b></div>' +
    '<div><span>BOOKS</span><b>$' + bn(bk) + 'bn</b></div><div><span>AVG COVER</span><b>' + (bk / wsz).toFixed(2) + 'x</b></div>';
}
function draw() { list.innerHTML = D.map(rowHtml).join(''); drawKpi(); detail(); }
function detail() {
  var d = D[sel], c = cur(d), by = BM[d.ten];
  var pts = [d.fv].concat(d.ipt != null ? [d.ipt] : [], d.g || [], d.l != null ? [d.l] : []);
  var lo = Math.min.apply(null, pts) - 6, hi = Math.max.apply(null, pts) + 6, pos = function (v) { return ((v - lo) / (hi - lo) * 100).toFixed(1) + '%'; };
  var ax = '<span class="fid-new-issue-mk-f" style="left:' + pos(d.fv) + '">FV ' + d.fv + '</span>';
  if (d.g) ax += '<i class="fid-new-issue-gr" style="left:' + pos(d.g[0]) + ';width:' + ((d.g[1] - d.g[0]) / (hi - lo) * 100).toFixed(1) + '%"></i>';
  if (d.ipt != null) ax += '<span class="fid-new-issue-mk-i" style="left:' + pos(d.ipt) + '">IPT ' + d.ipt + '</span>';
  if (d.l != null) ax += '<span class="fid-new-issue-mk-l" style="left:' + pos(d.l) + '">L ' + d.l + '</span>';
  var tight = d.ipt != null && c != null ? c - d.ipt : null;
  det.innerHTML = '<div class="fid-new-issue-dt"><span><b>' + d.tk + ' ' + d.ten + '</b> ' + d.nm + '</span><span>' + d.note + '</span></div>' +
    '<div class="fid-new-issue-ax">' + ax + '</div>' +
    '<div class="fid-new-issue-ds"><div><span>IPT→NOW</span><b>' + (tight != null ? sg(tight, tight % 1 ? 1 : 0) + 'bp' : '–') + '</b></div>' +
    '<div><span>NIC vs FV</span><b>' + (c != null ? sg(c - d.fv, (c - d.fv) % 1 ? 1 : 0) + 'bp' : '–') + '</b></div>' +
    '<div><span>UST ' + (d.ten === '6NC5' ? '5Y' : d.ten) + '</span><b>' + by.toFixed(3) + '%</b></div>' +
    '<div><span>' + (d.st === 'PRICED' ? 'RE-OFFER' : 'IMPLIED') + ' YLD</span><b>' + (c != null ? (by + c / 100).toFixed(3) + '%' : '–') + '</b></div></div>';
}
function select(i) {
  sel = Math.max(0, Math.min(D.length - 1, i));
  Array.prototype.forEach.call(list.children, function (el, j) { el.setAttribute('aria-selected', String(j === sel)); });
  var el = list.children[sel];
  if (el) {
    var top = el.offsetTop - list.offsetTop;
    if (top < list.scrollTop) list.scrollTop = top;
    else if (top + el.offsetHeight > list.scrollTop + list.clientHeight) list.scrollTop = top + el.offsetHeight - list.clientHeight;
  }
  detail();
}
function refreshRow(i, bump) {
  var d = D[i], el = list.children[i]; if (!el) return;
  var b = el.querySelector('[data-f="book"]'), c = el.querySelector('[data-f="cov"]');
  b.textContent = bn(d.book) + 'bn'; c.textContent = (d.book / d.size).toFixed(2) + 'x';
  if (bump) { b.classList.remove('fid-new-issue-bump'); void b.offsetWidth; b.classList.add('fid-new-issue-bump'); }
  drawKpi();
}
function sendIOI() {
  var d = D[sel], amt = parseFloat(inp.value);
  if (!isFinite(amt) || amt <= 0 || amt > 500) { msg.innerHTML = '<em>✖ IOI must be 0–500mm</em>'; return; }
  amt = Math.round(amt * 4) / 4;
  if (d.st === 'PRICED') { msg.innerHTML = '<em>✖ ' + d.tk + ' books closed</em> — allocations released'; return; }
  if (d.st === 'ANNCD') { msg.innerHTML = d.tk + ': no book open — <b>' + amt + 'mm</b> held as pre-IOI for IPTs'; return; }
  d.book += amt; ioiN++;
  var lvl = d.l != null ? '@ +' + d.l : d.g ? '@ +' + gtxt(d) : '@ IPT +' + d.ipt;
  msg.innerHTML = '<b>✔ IOI #' + ioiN + ' ' + amt + 'mm ' + d.tk + ' ' + lvl + '</b><br>book $' + bn(d.book) + 'bn · pro-rata est. ' + (amt * d.size / d.book).toFixed(2) + 'mm';
  refreshRow(sel, true);
}
list.addEventListener('click', function (e) { var r = e.target.closest('.fid-new-issue-row'); if (r) { select(+r.getAttribute('data-i')); root.focus(); } });
inp.addEventListener('keydown', function (e) {
  if (e.key === 'Enter') { e.preventDefault(); e.stopPropagation(); sendIOI(); }
  else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); root.focus(); }
  else if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
    e.preventDefault(); e.stopPropagation();
    var v = (parseFloat(inp.value) || 0) + (e.key === 'ArrowUp' ? 5 : -5); inp.value = String(Math.max(0, v));
  }
});
root.addEventListener('keydown', function (e) {
  if (e.target !== root) return;
  if (e.key === 'ArrowDown') { e.preventDefault(); select(sel + 1); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); select(sel - 1); }
  else if (e.key === 'Enter') { e.preventDefault(); msg.textContent = 'Ticket: ' + D[sel].tk + ' ' + D[sel].ten + ' — size, then ⏎'; inp.focus(); inp.select(); }
});
draw();
var seed = 7;
function rnd() { seed = (seed * 16807) % 2147483647; return seed / 2147483647; }
var timer = setInterval(function () {
  if (!root.isConnected) { clearInterval(timer); return; }
  /* orders keep arriving on deals with an open book */
  var open = D.map(function (d, i) { return i; }).filter(function (i) { return D[i].st === 'IPTS' || D[i].st === 'GUID'; });
  var i = open[Math.floor(rnd() * open.length)];
  D[i].book += 5 * Math.round((15 + rnd() * 120) / 5);
  refreshRow(i, true);
}, 1700);

