.fid-repo-board{--fp-bg:#0D1017;--fp-ln:#1D2331;--fp-tx:#D5DBE7;--fp-dim:#7A8499;--fp-mut:#4D566A;--fp-acc:#F2A93B;--fp-up:#35C98A;--fp-dn:#F25F6B;--fp-inf:#5AA9FF;box-sizing:border-box;width:100%;min-width:260px;background:var(--fp-bg);border:1px solid var(--fp-ln);border-radius:4px;color:var(--fp-tx);font:10px/1.35 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;overflow:hidden;outline:none}
