.fid-repo-board-ft kbd{font:inherit;color:var(--fp-dim);border:1px solid #262E40;border-radius:2px;padding:0 2px}
.fid-repo-board-g td{transition:background-color .2s ease}
@media (prefers-reduced-motion: reduce){
.fid-repo-board .fid-repo-board-g td{transition:none}
