var REF = [['SOFR', 3.63], ['TGCR', 3.60], ['BGCR', 3.60], ['ON RRP', 3.50], ['IORB', 3.65]], SOFR = 3.63;
var TERMS = [['O/N', 0, 1], ['1W', 0, 7], ['1M', 1, 0], ['3M', 3, 0]];   /* label, months, days */
/* px = clean price (32nds, priced off the 2Y 3.566 / 5Y 3.781 / 10Y 4.104 / 30Y 4.712 curve); ai = accrued per 100 at start date; pd = coupon period days for Act/Act carry (MBS and baskets accrue 30/360) */
var ROWS = [
  { c: 'UST GC', d: 'Tri-party GC basket', px: 100, ai: 0, cpn: null, hc: 2, r: [3.61, 3.62, 3.60, 3.55], ust: 1 },
  { c: 'UST 2Y', d: 'T 3.500 08/31/28', px: 99.875, ai: 0.23204, cpn: 3.5, pd: 181, hc: 2, r: [3.58, 3.59, 3.57, 3.53], ust: 1 },
  { c: 'UST 5Y', d: 'T 3.750 08/31/31', px: 99.859375, ai: 0.24862, cpn: 3.75, pd: 181, hc: 2, r: [3.49, 3.52, 3.53, 3.50], ust: 1 },
  { c: 'UST 10Y', d: 'T 4.000 08/15/36', px: 99.15625, ai: 0.43478, cpn: 4.0, pd: 184, hc: 2, r: [2.95, 3.10, 3.28, 3.40], ust: 1 },
  { c: 'UST 30Y', d: 'T 4.625 08/15/56', px: 98.609375, ai: 0.50272, cpn: 4.625, pd: 184, hc: 3, r: [3.56, 3.58, 3.57, 3.53], ust: 1 },
  { c: 'AGY MBS', d: 'FNCL 5.0 pool', px: 99.25, ai: 0.31944, cpn: 5.0, hc: 3, r: [3.74, 3.75, 3.73, 3.68] },
  { c: 'IG CORP', d: 'IG basket A–BBB', px: 98.4, ai: 1.2750, cpn: 5.1, hc: 5, r: [3.93, 3.95, 3.94, 3.90] },
  { c: 'HY CORP', d: 'HY basket BB–B', px: 96.8, ai: 1.8125, cpn: 7.25, hc: 10, r: [4.38, 4.40, 4.42, 4.40] }
];
var START = Date.UTC(2026, 8, 24), MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function ds(t) { var d = new Date(t); return (d.getUTCDate() < 10 ? '0' : '') + d.getUTCDate() + '-' + MON[d.getUTCMonth()]; }
/* modified following: roll weekends forward unless that crosses the month end */
function modFol(t) {
  var d = new Date(t), m = d.getUTCMonth(), x = t;
  while ([0, 6].indexOf(new Date(x).getUTCDay()) >= 0) x += 864e5;
  if (new Date(x).getUTCMonth() !== m) { x = t; while ([0, 6].indexOf(new Date(x).getUTCDay()) >= 0) x -= 864e5; }
  return x;
}
var ENDS = TERMS.map(function (tm) {
  var s = new Date(START), e = Date.UTC(s.getUTCFullYear(), s.getUTCMonth() + tm[1], s.getUTCDate() + tm[2]);
  e = modFol(e); return { t: e, days: Math.round((e - START) / 864e5) };
});
var face = 50000000, cr = 3, cc = 2;
var tbody = root.querySelector('tbody'), selEl = root.querySelector('.fid-repo-board-sel'), lines = root.querySelector('.fid-repo-board-lines'), inp = root.querySelector('[data-k="face"]');
root.querySelector('.fid-repo-board-ref').innerHTML = REF.map(function (r) { return '<div><span>' + r[0] + '</span><b>' + r[1].toFixed(2) + '</b></div>'; }).join('');
function r2(x) { return Math.round(x * 100) / 100; }
function fm(x) { var s = Math.abs(x).toFixed(2).split('.'); s[0] = s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ','); return (x < 0 ? '−' : '') + s.join('.'); }
function bp(x) { var v = Math.round(x * 100); return (v > 0 ? '+' : v < 0 ? '−' : '±') + Math.abs(v); }
function spec(i, j) { return ROWS[i].ust && i > 0 ? Math.round((ROWS[0].r[j] - ROWS[i].r[j]) * 100) : 0; }
function draw() {
  root.querySelectorAll('thead th').forEach(function (th, j) { th.classList.toggle('fid-repo-board-hl', j === cc + 1); });
  tbody.innerHTML = ROWS.map(function (row, i) {
    return '<tr' + (i === cr ? ' class="fid-repo-board-rh"' : '') + '><th scope="row" title="' + row.d + '">' + row.c + '</th>' + row.r.map(function (v, j) {
      var cls = []; if (spec(i, j) >= 10) cls.push('fid-repo-board-sp'); if (i === cr && j === cc) cls.push('fid-repo-board-on');
      return '<td role="gridcell" data-r="' + i + '" data-c="' + j + '" class="' + cls.join(' ') + '">' + v.toFixed(2) + '</td>';
    }).join('') + '</tr>';
  }).join('');
  calc();
}
function calc() {
  var row = ROWS[cr], rate = row.r[cc], e = ENDS[cc], days = e.days, sp = spec(cr, cc);
  selEl.innerHTML = '<b>' + row.c + '</b> ' + row.d + ' · <b>' + TERMS[cc][0] + '</b> ' + ds(START) + '→' + ds(e.t) + ' ' + days + 'd<br>' +
    'Repo <b>' + rate.toFixed(2) + '%</b> · SOFR ' + bp(rate - SOFR) + 'bp' +
    (row.ust && cr > 0 ? ' · <span class="' + (sp >= 10 ? 'fid-repo-board-s' : '') + '">' + (sp >= 10 ? '▾ SPECIAL ' : 'vs GC ') + (sp >= 10 ? sp : bp(-sp / 100)) + 'bp</span>' : '');
  var dirty = row.px + row.ai, mv = r2(face * dirty / 100), cash = r2(mv * (1 - row.hc / 100)), intr = r2(cash * rate / 100 * days / 360), rep = r2(cash + intr);
  root.querySelector('[data-o="dp"]').textContent = dirty.toFixed(5);
  root.querySelector('[data-o="hc"]').textContent = row.hc.toFixed(1) + '%';
  var h = [['Market value', fm(mv)], ['Cash lent (start)', fm(cash)],
           ['Repo int ' + rate.toFixed(2) + '%×' + days + '/360', fm(intr)], ['Repurchase (end)', fm(rep), 'fid-repo-board-tot']];
  if (row.cpn != null) {
    var acc = r2(face * row.cpn / 100 * (row.pd ? days / (2 * row.pd) : days / 360)), carry = r2(acc - intr);
    h.push(['Cpn accr ' + row.cpn.toFixed(3) + (row.pd ? '% A/A' : '% 30/360'), fm(acc)]);
    h.push(['Net carry ' + days + 'd', (carry > 0 ? '▲ +' : carry < 0 ? '▼ ' : '') + fm(carry), 'fid-repo-board-tot ' + (carry >= 0 ? 'fid-repo-board-u' : 'fid-repo-board-d')]);
  } else h.push(['Net carry', 'n/a · GC basket']);
  lines.innerHTML = h.map(function (l) { return '<div' + (l[2] ? ' class="' + l[2] + '"' : '') + '><span>' + l[0] + '</span><b>' + l[1] + '</b></div>'; }).join('');
  inp.value = (face / 1e6).toFixed(3); inp.classList.remove('fid-repo-board-err');
}
tbody.addEventListener('click', function (e) {
  var td = e.target.closest('td'); if (!td) return;
  cr = +td.getAttribute('data-r'); cc = +td.getAttribute('data-c'); draw(); root.focus();
});
inp.addEventListener('keydown', function (e) {
  if (e.key === 'Enter' || e.key === 'ArrowUp' || e.key === 'ArrowDown') {
    e.preventDefault(); e.stopPropagation();
    var v = parseFloat(inp.value.replace(/,/g, ''));
    if (e.key !== 'Enter') v = (isFinite(v) ? v : 0) + (e.key === 'ArrowUp' ? 5 : -5) * (e.shiftKey ? 5 : 1);
    if (!isFinite(v) || v <= 0 || v > 10000) { inp.classList.add('fid-repo-board-err'); return; }
    face = Math.round(v * 1000) * 1000; calc();
  } else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); calc(); root.focus(); }
});
inp.addEventListener('blur', calc);
root.addEventListener('keydown', function (e) {
  if (e.target !== root) return;
  var k = e.key, hit = true;
  if (k === 'ArrowUp') cr = Math.max(0, cr - 1);
  else if (k === 'ArrowDown') cr = Math.min(ROWS.length - 1, cr + 1);
  else if (k === 'ArrowLeft') cc = Math.max(0, cc - 1);
  else if (k === 'ArrowRight') cc = Math.min(3, cc + 1);
  else if (k === 'f' || k === 'F') { e.preventDefault(); inp.focus(); inp.select(); return; }
  else hit = false;
  if (hit) { e.preventDefault(); draw(); }
});
draw();

css:
.fid-rv-scatter{--fv-bg:#0D1017;--fv-ln:#1D2331;--fv-tx:#D5DBE7;--fv-dim:#7A8499;--fv-mut:#4D566A;--fv-acc:#F2A93B;--fv-ca:#5AA9FF;--fv-cb:#E0A34A;--fv-cheap:#35C98A;--fv-rich:#F25F6B;box-sizing:border-box;width:100%;min-width:260px;background:var(--fv-bg);border:1px solid var(--fv-ln);border-radius:4px;color:var(--fv-tx);font:10px/1.35 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;overflow:hidden;outline:none}
.fid-rv-scatter *{box-sizing:border-box}
.fid-rv-scatter:focus-visible{box-shadow:0 0 0 1px var(--fv-acc)}
.fid-rv-scatter-hd{display:flex;justify-content:space-between;align-items:center;gap:6px;padding:5px 8px 3px;background:linear-gradient(#141925,#0D1017)}
.fid-rv-scatter-t{font:700 10.5px/1 system-ui,-apple-system,Segoe UI,sans-serif;letter-spacing:.1em;color:var(--fv-acc);white-space:nowrap}
.fid-rv-scatter-tabs{display:flex;border:1px solid #262E40;border-radius:3px;overflow:hidden}
.fid-rv-scatter-tabs button{all:unset;cursor:pointer;padding:1px 7px;font:600 9px/1.5 system-ui,-apple-system,Segoe UI,sans-serif;color:var(--fv-dim)}
.fid-rv-scatter-tabs button[aria-selected="true"]{background:#262E40;color:#fff}
.fid-rv-scatter-tabs button:focus-visible{outline:1px solid var(--fv-acc);outline-offset:-1px}
.fid-rv-scatter-lg{display:flex;flex-wrap:wrap;gap:2px 10px;padding:0 8px 2px;color:var(--fv-dim);font-size:9px}
.fid-rv-scatter-lg i{display:inline-block;width:7px;height:7px;margin-right:3px;vertical-align:0}
.fid-rv-scatter-ka{background:var(--fv-ca);border-radius:50%}
.fid-rv-scatter-kb{background:var(--fv-cb)}
.fid-rv-scatter-eq{margin-left:auto;color:var(--fv-mut)}
.fid-rv-scatter-plot{position:relative;border-top:1px solid var(--fv-ln);border-bottom:1px solid var(--fv-ln);background:#0B0E14}
.fid-rv-scatter-svg{display:block;width:100%;height:184px;font-family:ui-monospace,Menlo,Consolas,monospace}
.fid-rv-scatter-svg .fid-rv-scatter-grid{stroke:#1A2030;stroke-width:1}
.fid-rv-scatter-svg .fid-rv-scatter-axis{fill:var(--fv-mut);font-size:8.5px}
.fid-rv-scatter-svg .fid-rv-scatter-fa{fill:none;stroke:var(--fv-ca);stroke-width:1.3;stroke-dasharray:4 3;opacity:.8}
.fid-rv-scatter-svg .fid-rv-scatter-fb{fill:none;stroke:var(--fv-cb);stroke-width:1.3;stroke-dasharray:4 3;opacity:.8}
.fid-rv-scatter-svg .fid-rv-scatter-pa{fill:var(--fv-ca)}
.fid-rv-scatter-svg .fid-rv-scatter-pb{fill:var(--fv-cb)}
.fid-rv-scatter-svg .fid-rv-scatter-pt{cursor:pointer;stroke:#0B0E14;stroke-width:1;transition:opacity .2s ease}
.fid-rv-scatter-svg .fid-rv-scatter-dim{opacity:.12;pointer-events:none}
.fid-rv-scatter-svg .fid-rv-scatter-stc{stroke:var(--fv-cheap);stroke-width:1}
.fid-rv-scatter-svg .fid-rv-scatter-str{stroke:var(--fv-rich);stroke-width:1}
.fid-rv-scatter-svg .fid-rv-scatter-ring{fill:none;stroke:#fff;stroke-width:1.2}
.fid-rv-scatter-svg .fid-rv-scatter-lbl{fill:#fff;font-size:9px;font-weight:700;paint-order:stroke;stroke:#0B0E14;stroke-width:3px}
.fid-rv-scatter-rd{padding:4px 8px;background:#0A0D13;font-size:9.5px;line-height:1.45;min-height:32px;color:var(--fv-dim)}
.fid-rv-scatter-rd b{color:var(--fv-tx);font-weight:600}
.fid-rv-scatter-c{color:var(--fv-cheap)}
.fid-rv-scatter-r{color:var(--fv-rich)}
.fid-rv-scatter-top{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--fv-ln)}
.fid-rv-scatter-top div{padding:3px 8px;min-width:0}
.fid-rv-scatter-top div:first-child{border-right:1px solid #141925}
.fid-rv-scatter-top h4{margin:0 0 1px;font:600 8px/1.3 system-ui,-apple-system,Segoe UI,sans-serif;letter-spacing:.08em}
.fid-rv-scatter-top p{margin:0;display:flex;justify-content:space-between;gap:4px;font-size:9.5px;white-space:nowrap}
.fid-rv-scatter-top p span:first-child{overflow:hidden;text-overflow:ellipsis}
.fid-rv-scatter-ft{padding:3px 8px;border-top:1px solid var(--fv-ln);color:var(--fv-mut);font-size:8.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fid-rv-scatter-ft kbd{font:inherit;color:var(--fv-dim);border:1px solid #262E40;border-radius:2px;padding:0 2px}
@media (prefers-reduced-motion: reduce){
.fid-rv-scatter .fid-rv-scatter-svg .fid-rv-scatter-pt{transition:none}
}

