/* issue, rating, bucket, modified duration (yrs), OAS (bp) */
var B = [
  ['PEP 4.450 05/15/28', 'A+', 'A', 1.5, 44], ['HD 4.900 04/15/29', 'A', 'A', 2.3, 52], ['KO 4.650 08/14/33', 'A+', 'A', 5.9, 76],
  ['WMT 4.100 04/15/34', 'AA', 'A', 6.4, 70], ['UNH 5.150 07/15/35', 'A+', 'A', 7.1, 98], ['TXN 5.050 05/18/37', 'A+', 'A', 8.4, 88],
  ['PG 4.550 10/29/44', 'AA-', 'A', 14.0, 96], ['AAPL 4.850 05/10/53', 'AA+', 'A', 16.2, 92],
  ['VZ 4.016 12/03/29', 'BBB+', 'BBB', 2.9, 88], ['ORCL 2.950 04/01/30', 'BBB', 'BBB', 3.3, 112], ['CVS 5.250 01/30/31', 'BBB', 'BBB', 3.9, 118],
  ['DELL 5.300 04/01/32', 'BBB', 'BBB', 4.9, 110], ['AMGN 5.250 03/02/33', 'BBB+', 'BBB', 5.4, 98], ['GS 5.050 07/23/33', 'BBB+', 'BBB', 5.6, 104],
  ['BA 6.528 05/01/34', 'BBB-', 'BBB', 5.9, 158], ['T 5.400 02/15/34', 'BBB', 'BBB', 6.1, 116], ['HCA 5.450 09/15/34', 'BBB-', 'BBB', 6.6, 132],
  ['ORCL 5.550 02/06/53', 'BBB', 'BBB', 14.6, 185], ['T 3.500 09/15/53', 'BBB', 'BBB', 15.3, 168]
].map(function (r, i) { return { i: i, d: r[0], tk: r[0].split(' ')[0], rt: r[1], g: r[2], md: r[3], oas: r[4] }; });
/* OLS of OAS on ln(MD) per rating bucket */
var FIT = {};
['A', 'BBB'].forEach(function (g) {
  var p = B.filter(function (b) { return b.g === g; }), n = p.length, sx = 0, sy = 0, sxx = 0, sxy = 0;
  p.forEach(function (b) { var x = Math.log(b.md); sx += x; sy += b.oas; sxx += x * x; sxy += x * b.oas; });
  var bb = (n * sxy - sx * sy) / (n * sxx - sx * sx), aa = (sy - bb * sx) / n;
  p.forEach(function (b) { b.fit = aa + bb * Math.log(b.md); b.res = b.oas - b.fit; });
  var sse = p.reduce(function (s, b) { return s + b.res * b.res; }, 0), sst = p.reduce(function (s, b) { return s + Math.pow(b.oas - sy / n, 2); }, 0);
  var se = Math.sqrt(sse / (n - 2));
  p.forEach(function (b) { b.z = b.res / se; });
  FIT[g] = { a: aa, b: bb, se: se, r2: 1 - sse / sst, n: n };
});
var filt = 'ALL', sel = B[14];
var svg = root.querySelector('svg'), rd = root.querySelector('.fid-rv-scatter-rd'), topEl = root.querySelector('.fid-rv-scatter-top'), eq = root.querySelector('.fid-rv-scatter-eq');
var NS = 'http://www.w3.org/2000/svg';
function vis(b) { return filt === 'ALL' || b.g === filt; }
function sg(x, d) { return (x > 0 ? '+' : x < 0 ? '−' : '±') + Math.abs(x).toFixed(d); }
function el(tag, attrs, parent) { var e = document.createElementNS(NS, tag); for (var k in attrs) e.setAttribute(k, attrs[k]); if (parent) parent.appendChild(e); return e; }
function draw() {
  var W = Math.max(240, Math.round(svg.getBoundingClientRect().width || 320)), H = 184, L = 30, R = 8, T = 16, Bm = 28;
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  while (svg.firstChild) svg.removeChild(svg.firstChild);
  var X0 = 0, X1 = 17, pts = B.filter(vis), lo = Math.min.apply(null, pts.map(function (b) { return b.oas; })), hi = Math.max.apply(null, pts.map(function (b) { return b.oas; }));
  var Y0 = Math.floor((lo - 10) / 20) * 20, Y1 = Math.ceil((hi + 10) / 20) * 20;
  var sx = function (v) { return L + (v - X0) / (X1 - X0) * (W - L - R); }, sy = function (v) { return T + (Y1 - v) / (Y1 - Y0) * (H - T - Bm); };
  for (var x = 0; x <= 16; x += 2) {
    el('line', { x1: sx(x), x2: sx(x), y1: T, y2: H - Bm, 'class': 'fid-rv-scatter-grid' }, svg);
    el('text', { x: sx(x), y: H - Bm + 11, 'text-anchor': 'middle', 'class': 'fid-rv-scatter-axis' }, svg).textContent = x;
  }
  var step = (Y1 - Y0) > 120 ? 40 : 20;
  for (var y = Y0; y <= Y1; y += step) {
    el('line', { x1: L, x2: W - R, y1: sy(y), y2: sy(y), 'class': 'fid-rv-scatter-grid' }, svg);
    el('text', { x: L - 4, y: sy(y) + 3, 'text-anchor': 'end', 'class': 'fid-rv-scatter-axis' }, svg).textContent = y;
  }
  el('text', { x: W - R, y: H - 3, 'text-anchor': 'end', 'class': 'fid-rv-scatter-axis' }, svg).textContent = 'MOD DUR (yrs) →';
  el('text', { x: 4, y: 9, 'class': 'fid-rv-scatter-axis' }, svg).textContent = 'OAS bp';
  ['A', 'BBB'].forEach(function (g) {
    if (filt !== 'ALL' && filt !== g) return;
    var f = FIT[g], d = '';
    for (var m = 1; m <= 16.6; m += 0.2) d += (d ? 'L' : 'M') + sx(m).toFixed(1) + ' ' + sy(f.a + f.b * Math.log(m)).toFixed(1);
    el('path', { d: d, 'class': g === 'A' ? 'fid-rv-scatter-fa' : 'fid-rv-scatter-fb' }, svg);
  });
  B.forEach(function (b) {
    if (!vis(b)) return;
    el('line', { x1: sx(b.md), x2: sx(b.md), y1: sy(b.fit), y2: sy(b.oas), 'class': b.res >= 0 ? 'fid-rv-scatter-stc' : 'fid-rv-scatter-str' }, svg);
  });
  B.forEach(function (b) {
    if (!vis(b)) return;
    var cx = sx(b.md), cy = sy(b.oas), p;
    if (b.g === 'A') p = el('circle', { cx: cx, cy: cy, r: 3.6 }, svg);
    else p = el('rect', { x: cx - 3.3, y: cy - 3.3, width: 6.6, height: 6.6 }, svg);
    p.setAttribute('class', 'fid-rv-scatter-pt ' + (b.g === 'A' ? 'fid-rv-scatter-pa' : 'fid-rv-scatter-pb'));
    p.setAttribute('data-i', b.i);
    el('title', {}, p).textContent = b.d + ' · MD ' + b.md.toFixed(1) + ' · OAS ' + b.oas;
  });
  if (vis(sel)) {
    var cx = sx(sel.md), cy = sy(sel.oas);
    el('circle', { cx: cx, cy: cy, r: 7, 'class': 'fid-rv-scatter-ring' }, svg);
    var right = cx < W * 0.7;
    el('text', { x: cx + (right ? 10 : -10), y: cy - 6, 'text-anchor': right ? 'start' : 'end', 'class': 'fid-rv-scatter-lbl' }, svg).textContent = sel.tk + ' ' + sg(sel.res, 1);
  }
  eq.textContent = (filt === 'ALL' ? ['A', 'BBB'] : [filt]).map(function (g) { return g + ' R² ' + FIT[g].r2.toFixed(2); }).join(' · ');
  readout();
}
function readout() {
  var b = sel, f = FIT[b.g], cheap = b.res >= 0;
  rd.innerHTML = '<b>' + b.d + '</b> · ' + b.rt + ' · MD <b>' + b.md.toFixed(1) + '</b> · OAS <b>' + b.oas + '</b> · fit ' + b.fit.toFixed(1) + '<br>' +
    '<span class="' + (cheap ? 'fid-rv-scatter-c' : 'fid-rv-scatter-r') + '">' + (cheap ? '▲ CHEAP ' : '▼ RICH ') + sg(b.res, 1) + 'bp</span> vs ' + b.g +
    ' curve · Z ' + sg(b.z, 2) + 'σ (se ' + f.se.toFixed(1) + 'bp, n=' + f.n + ')';
  var v = B.filter(vis).slice().sort(function (p, q) { return q.z - p.z; });
  function lst(a, cls) { return a.map(function (x) { return '<p><span>' + x.tk + ' ' + x.d.slice(-2) + '</span><span class="' + cls + '">' + sg(x.res, 1) + '</span></p>'; }).join(''); }
  var ch = v.filter(function (x) { return x.res > 0; }).slice(0, 3), ri = v.filter(function (x) { return x.res < 0; }).reverse().slice(0, 3);
  topEl.innerHTML = '<div><h4 class="fid-rv-scatter-c">▲ CHEAPEST vs FIT</h4>' + lst(ch, 'fid-rv-scatter-c') + '</div>' +
    '<div><h4 class="fid-rv-scatter-r">▼ RICHEST vs FIT</h4>' + lst(ri, 'fid-rv-scatter-r') + '</div>';
}
function order() { return B.filter(vis).slice().sort(function (p, q) { return p.md - q.md || p.oas - q.oas; }); }
function setF(f) {
  filt = f;
